// Zoekplan van de app → invoer voor de Apify Google Search Scraper
const body = $('Webhook: search request').first().json.body;
const plan = Array.isArray(body.searchPlan) && body.searchPlan.length
  ? body.searchPlan
  : (body.searchQueries || []).map((query) => ({ query, kind: 'job' }));

return [{
  json: {
    runId: body.runId,
    callbackUrl: body.callbackUrl,
    plan,
    apifyInput: {
      queries: plan.map((entry) => entry.query).join('\n'),
      countryCode: 'nl',
      languageCode: 'en',
      maxPagesPerQuery: 1,
      resultsPerPage: 10,
      mobileResults: false,
      saveHtml: false,
      saveHtmlToKeyValueStore: false,
    },
  },
}];

// Google-resultaten → ruwe items voor de app (title, url, description, kind, query).
// De app vult bedrijf, type, locatie en 'why now' zelf aan met AI (of regels).
const input = $('Build Apify input').first().json;
const kindByQuery = new Map(input.plan.map((entry) => [String(entry.query).trim().toLowerCase(), entry.kind]));
const seen = new Set();
const items = [];

for (const page of $input.all()) {
  const term = String(page.json.searchQuery?.term ?? '').trim();
  const kind = kindByQuery.get(term.toLowerCase()) ?? 'job';
  for (const result of page.json.organicResults ?? []) {
    if (!result.url || seen.has(result.url)) continue;
    seen.add(result.url);
    items.push({ title: result.title, url: result.url, description: result.description, kind, query: term, source: 'web' });
  }
}

return [{ json: { runId: input.runId, callbackUrl: input.callbackUrl, items: items.slice(0, 60) } }];

// Eigen websites van bedrijven (geen jobboards, eventplatforms of nieuwssites) → contactgegevens zoeken
const PLATFORMS = ['linkedin.', 'indeed.', 'glassdoor.', 'eventbrite.', 'meetup.com', 'lu.ma', 'luma.com', 'devpost.com', 'crunchbase.com', 'dealroom.co', 'wellfound.com', 'facebook.com', 'x.com', 'twitter.com', 'medium.com', 'youtube.com', 'wikipedia.org', 'reddit.com', 'instagram.com', 'nos.nl', 'nu.nl', 'fd.nl', 'emerce.nl', 'sprout.nl', 'techcrunch.com', 'tweakers.net', 'news.google.com', 'werkzoeken.nl', 'nationalevacaturebank.nl', 'studentjob.nl', 'iamexpat.nl'];
const MAX_SITES = 10;
const hosts = [];

for (const item of $('Map results').first().json.items) {
  let host = '';
  try {
    host = new URL(item.url).hostname.replace(/^www\./, '');
  } catch {
    continue;
  }
  if (PLATFORMS.some((platform) => host.includes(platform)) || hosts.includes(host)) continue;
  hosts.push(host);
  if (hosts.length >= MAX_SITES) break;
}

return [{ json: { startUrls: hosts.map((host) => ({ url: `https://${host}/` })) } }];

// Beste e-mailadres per domein aan de items hangen (jobs@/careers@ > hello@/info@ > de rest)
const mapped = $('Map results').first().json;
let rows = [];
try {
  rows = $('Apify: Contact details').all().map((item) => item.json);
} catch {
  rows = []; // geen bedrijfssites gevonden: contact-stap is overgeslagen
}

const rank = (email) =>
  /^(jobs|careers?|werken|recruit\w*|talent|hr|people)@/.test(email) ? 0 : /^(hello|hi|info|contact)@/.test(email) ? 1 : 2;
const emailByHost = new Map();

for (const row of rows) {
  let host = String(row.domain || '').replace(/^www\./, '');
  if (!host && row.url) {
    try {
      host = new URL(row.url).hostname.replace(/^www\./, '');
    } catch {}
  }
  const emails = (row.emails || [])
    .map((email) => String(email).trim().toLowerCase())
    .filter((email) => email.includes('@') && !/\.(png|jpe?g|gif|webp|svg)$/.test(email));
  if (!host || emails.length === 0) continue;
  const best = emails.sort((a, b) => rank(a) - rank(b))[0];
  if (!emailByHost.has(host) || rank(best) < rank(emailByHost.get(host))) emailByHost.set(host, best);
}

const items = mapped.items.map((item) => {
  let host = '';
  try {
    host = new URL(item.url).hostname.replace(/^www\./, '');
  } catch {}
  const email = emailByHost.get(host);
  return email ? { ...item, contact: { email } } : item;
});

return [{ json: { runId: mapped.runId, callbackUrl: mapped.callbackUrl, done: true, items } }];
